"""Maximum-matching tokenizer for a whitespace-free script."""

DICTIONARY = {
    'ka', 'kata', 'tana', 'na', 'nami', 'mi', 'miso', 'so',
    'sora', 'ra', 'rako', 'ko', 'kota', 'ta', 'tami',
}

MAX_WORD_LEN = max(len(w) for w in DICTIONARY)


class TokenizeError(Exception):
    def __init__(self, position: int):
        self.position = position
        super().__init__(f"cannot tokenize at position {position}")


def _longest_prefix(s: str, i: int):
    """Longest dictionary word starting at i, or None."""
    for length in range(min(MAX_WORD_LEN, len(s) - i), 0, -1):
        if s[i:i + length] in DICTIONARY:
            return s[i:i + length]
    return None


def tokenize_forward(s: str) -> list:
    tokens = []
    i = 0
    while i < len(s):
        w = _longest_prefix(s, i)
        if w is None:
            raise TokenizeError(i)
        tokens.append(w)
        i += len(w)
    return tokens


def _longest_suffix_ending_at(s: str, j: int):
    """Longest dictionary word ending at (exclusive) index j, or None."""
    start_min = max(0, j - MAX_WORD_LEN)
    for start in range(start_min, j):
        if s[start:j] in DICTIONARY:
            return start, s[start:j]
    return None


def tokenize_backward(s: str) -> list:
    spans = []  # (start, end)
    j = len(s)
    while j > 0:
        hit = _longest_suffix_ending_at(s, j)
        if hit is None:
            raise TokenizeError(j)  # stuck: no dictionary word ends here
        spans.append(hit[0])
        j = hit[0]
    spans.reverse()
    return [s[a:b] for a, b in spans]


def tokenize_best(s: str) -> list:
    try:
        fwd = tokenize_forward(s)
    except TokenizeError:
        return tokenize_backward(s)
    try:
        bwd = tokenize_backward(s)
    except TokenizeError:
        return fwd
    return fwd if len(fwd) <= len(bwd) else bwd

