import itertools
from tokenizer import tokenize_forward, tokenize_backward
D = ['ka','kata','tana','na','nami','mi','miso','so','sora','ra','rako','ko','kota','ta','tami']
fwd_gt_bwd = []
bwd_gt_fwd = []
for n in range(2, 5):
    for combo in itertools.product(D, repeat=n):
        s = ''.join(combo)
        try:
            f, b = tokenize_forward(s), tokenize_backward(s)
        except Exception:
            continue
        if len(f) > len(b) and len(fwd_gt_bwd) < 3:
            fwd_gt_bwd.append((s, f, b))
        if len(b) > len(f) and len(bwd_gt_fwd) < 3:
            bwd_gt_fwd.append((s, f, b))
    if fwd_gt_bwd and bwd_gt_fwd:
        break
print("forward worse:", fwd_gt_bwd)
print("backward worse:", bwd_gt_fwd)
